import torch

@torch.no_grad()
def run(A, B):
    return torch.bmm(A, B.transpose(-2, -1))

import torch

@torch.no_grad()
def run(A, B):
    # Compute in fp32 for higher precision accumulation
    result = torch.bmm(A.float(), B.float())
    return result.to(torch.bfloat16)
